const $=s=>document.querySelector(s), state={stops:[],routes:[],trips:[],times:[],calendar:[],dates:[],rows:[]};
const dayNames=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
$('#serviceDate').value=new Date().toISOString().slice(0,10);
for(const id of ['feedUrl','apiKey']) $('#'+id).value=localStorage.getItem('ybt-'+id)||$('#'+id).value;
$('#saveSettings').onclick=()=>{for(const id of ['feedUrl','apiKey'])localStorage.setItem('ybt-'+id,$('#'+id).value); say('設定をこのブラウザに保存しました。')};
function say(x){$('#status').textContent=x} function csv(text){const rows=[];let r=[],v='',q=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&q&&n==='"'){v+='"';i++}else if(c==='"')q=!q;else if(c===','&&!q){r.push(v);v=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&n==='\n')i++;r.push(v);if(r.some(x=>x!==''))rows.push(r);r=[];v=''}else v+=c}r.push(v);if(r.some(x=>x!==''))rows.push(r);const h=rows.shift()||[];return rows.map(x=>Object.fromEntries(h.map((k,i)=>[k.replace(/^\uFEFF/,''),x[i]||''])))}
async function readZip(file){try{const z=await JSZip.loadAsync(file), get=async n=>z.file(n)?csv(await z.file(n).async('text')):[];[state.stops,state.routes,state.trips,state.times,state.calendar,state.dates]=await Promise.all(['stops.txt','routes.txt','trips.txt','stop_times.txt','calendar.txt','calendar_dates.txt'].map(get));if(!state.stops.length||!state.times.length)throw Error('必要なGTFSファイルが見つかりません');const info=await get('feed_info.txt');$('#feedInfo').textContent=(info[0]?.feed_version||file.name);$('#controls').classList.remove('disabled');$('#results').classList.remove('disabled');say(`${file.name} を読み込みました。停留所を検索してください。`);findStops()}catch(e){say('読込エラー: '+e.message)}}
$('#zipFile').onchange=e=>e.target.files[0]&&readZip(e.target.files[0]);
$('#fetchBtn').onclick=async()=>{let u=$('#feedUrl').value.trim(),k=$('#apiKey').value.trim();if(!k)return say('APIキーを設定するか、ZIPを手動で選んでください。');if(!/acl:consumerKey=/.test(u))u+=(u.includes('?')?'&':'?')+'acl:consumerKey='+encodeURIComponent(k);try{say('公式データを取得中…');let r=await fetch(u);if(!r.ok)throw Error(r.status+' '+r.statusText);await readZip(await r.blob())}catch(e){say('直接取得できませんでした（CORS等）: ZIPを手動で選択してください。 '+e.message)}};
function active(){const d=new Date($('#serviceDate').value+'T00:00:00'),ds=$('#serviceDate').value.replaceAll('-',''),wk=dayNames[d.getDay()],s=new Set(state.calendar.filter(x=>x.start_date<=ds&&x.end_date>=ds&&x[wk]==='1').map(x=>x.service_id));state.dates.filter(x=>x.date===ds).forEach(x=>x.exception_type==='1'?s.add(x.service_id):s.delete(x.service_id));return s}
function options(el, items){el.innerHTML='';items.forEach(([v,t])=>el.add(new Option(t,v)))}
function findStops(){let q=$('#stopSearch').value.trim().toLowerCase(), names=[...new Set(state.stops.filter(s=>(s.stop_name||'').toLowerCase().includes(q)).map(s=>s.stop_name))].sort();options($('#stopSelect'),names.map(x=>[x,x]));platforms()} $('#searchBtn').onclick=findStops;$('#stopSelect').onchange=platforms;$('#platformSelect').onchange=routes;
function platforms(){let ss=state.stops.filter(s=>s.stop_name===$('#stopSelect').value);options($('#platformSelect'),[['','すべての乗り場'],...ss.map(s=>[s.stop_id,`${s.platform_code||'指定なし'} — ${s.stop_id}`])]);routes()}
function stopIds(){return $('#platformSelect').value?[$('#platformSelect').value]:state.stops.filter(s=>s.stop_name===$('#stopSelect').value).map(s=>s.stop_id)}
function routes(){let ids=new Set(stopIds()), sv=active(), found=new Set(state.times.filter(x=>ids.has(x.stop_id)).map(x=>x.trip_id)), rmap=Object.fromEntries(state.routes.map(x=>[x.route_id,x])), out={};state.trips.filter(t=>found.has(t.trip_id)&&(!sv.size||sv.has(t.service_id))).forEach(t=>{let r=rmap[t.route_id]||{};out[t.route_id]=`${r.route_short_name||t.route_id}  ${r.route_long_name||''}`.trim()});options($('#routeSelect'),Object.entries(out).sort((a,b)=>a[1].localeCompare(b[1],'ja')))}
function secs(s){let a=(s||'').split(':').map(Number);return a.length>1?a[0]*3600+a[1]*60+(a[2]||0):1e9}function time(s){let a=(s||'').split(':');return a.length>1 ? String(+a[0]).padStart(2,'0')+':'+a[1] : s}
$('#generateBtn').onclick=()=>{routes();let ids=new Set(stopIds()), sv=active(), selected=[...$('#routeSelect').selectedOptions].map(x=>x.value), all=[...$('#routeSelect').options].map(x=>x.value), wanted=new Set(selected.length?selected:all), tmap=Object.fromEntries(state.trips.filter(t=>wanted.has(t.route_id)&&(!sv.size||sv.has(t.service_id))).map(t=>[t.trip_id,t])),rmap=Object.fromEntries(state.routes.map(r=>[r.route_id,r])),sm=Object.fromEntries(state.stops.map(s=>[s.stop_id,s])),filter=$('#destination').value;state.rows=state.times.filter(x=>ids.has(x.stop_id)&&tmap[x.trip_id]).map(x=>{let t=tmap[x.trip_id],r=rmap[t.route_id]||{},dest=t.trip_headsign||r.route_long_name||'';return {time:time(x.departure_time||x.arrival_time),route:r.route_short_name||t.route_id,destination:dest,platform:sm[x.stop_id]?.platform_code||''}}).filter(x=>!filter||x.destination.includes(filter)).sort((a,b)=>secs(a.time)-secs(b.time));$('#timetable').innerHTML=state.rows.map(r=>`<tr><td>${r.time}</td><td>${esc(r.route)}</td><td>${esc(r.destination)}</td><td>${esc(r.platform)}</td></tr>`).join('');$('#tableTitle').textContent=`${$('#stopSelect').value} 統合時刻表`;$('#tableMeta').textContent=`${$('#serviceDate').value} · ${state.rows.length}件`;say(`${state.rows.length}件の時刻表を生成しました。`)};function esc(x){return String(x).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}
function stamp(){return `${$('#stopSelect').value||'bus'}_${$('#serviceDate').value}`}function records(){return [['時刻','系統','行き先','乗り場'],...state.rows.map(r=>[r.time,r.route,r.destination,r.platform])]}document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>{if(!state.rows.length)return say('先に時刻表を生成してください。');let k=b.dataset.export;if(k==='xlsx'){let ws=XLSX.utils.aoa_to_sheet(records()),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'時刻表');XLSX.writeFile(wb,stamp()+'.xlsx')}else if(k==='html'){let html='<!doctype html><meta charset="utf-8"><title>'+esc($('#tableTitle').textContent)+'</title><h1>'+esc($('#tableTitle').textContent)+'</h1><table border="1">'+$('#results table').innerHTML;download(html,stamp()+'.html','text/html')}else{let {jsPDF}=window.jspdf,doc=new jsPDF();doc.setFontSize(14);doc.text('Yokohama Municipal Bus Timetable',14,18);doc.setFontSize(10);state.rows.forEach((r,i)=>doc.text(`${r.time}  ${r.route}  ${r.destination}`,14,30+i*7));doc.save(stamp()+'.pdf')}});function download(s,n,t){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([s],{type:t}));a.download=n;a.click();URL.revokeObjectURL(a.href)}
